import { useEffect, useId, useRef, useState } from 'react';
import { saveQCParameter } from '../../lib/vendor-sampling';
export default function QCParametersModal({ options, onClose, onSaved }) {
  const ref = useRef(null), pending = useRef(false), prefix = useId();
  const empty = { parameter_name: '', category_id: '', weight: 1, display_order: 0, is_active: true };
  const [form, setForm] = useState(empty), [editing, setEditing] = useState(null), [busy, setBusy] = useState(false), [error, setError] = useState('');
  useEffect(() => { const d = ref.current; d.showModal(); return () => d.close(); }, []);
  const submit = async (e) => { e.preventDefault(); if (pending.current) return; pending.current = true; setBusy(true); setError(''); try { await saveQCParameter(form, editing); setForm(empty); setEditing(null); onSaved(); } catch (err) { setError(err.message); } finally { pending.current = false; setBusy(false); } };
  return <dialog ref={ref} aria-labelledby={prefix + 'title'} onCancel={(e) => { e.preventDefault(); if (!busy) onClose(); }} className="m-auto w-[calc(100%-2rem)] max-w-3xl max-h-[90vh] overflow-y-auto rounded-xl border border-white/10 bg-ink-900 text-white p-5 backdrop:bg-black/70">
    <div className="flex justify-between items-center gap-3"><h2 id={prefix + 'title'} className="text-lg font-semibold">Rubrik QC</h2><button className="btn-secondary" onClick={onClose} disabled={busy}>Tutup rubrik</button></div>
    <p className="text-xs text-ink-400 my-3">Perubahan rubrik berlaku untuk pemeriksaan baru. Hasil lama menyimpan nama dan bobot asli.</p>
    <div className="space-y-2 mb-5">{options.parameters.map((p) => <div key={p.id} className="flex items-center justify-between gap-3 p-3 bg-white/5 rounded-lg"><div><p className="text-sm">{p.parameter_name} {!p.is_active && <span className="badge-gray">Nonaktif</span>}</p><p className="text-xs text-ink-400">{options.categories.find((c) => c.id === p.category_id)?.name || 'Semua kategori'} · bobot {p.weight}</p></div><button className="btn-secondary text-xs" onClick={() => { setEditing(p.id); setForm({ ...p, category_id: p.category_id || '' }); }}>Edit rubrik {p.parameter_name}</button></div>)}</div>
    <form className="space-y-3" onSubmit={submit}><h3 className="font-medium">{editing ? 'Edit parameter' : 'Tambah parameter'}</h3><div className="grid sm:grid-cols-2 gap-3">
      <div><label className="label" htmlFor={prefix + 'name'}>Nama parameter *</label><input id={prefix + 'name'} className="input" required minLength={2} maxLength={150} value={form.parameter_name} disabled={busy} onChange={(e) => setForm((s) => ({ ...s, parameter_name: e.target.value }))} /></div>
      <div><label className="label" htmlFor={prefix + 'category'}>Kategori rubrik</label><select id={prefix + 'category'} className="input" disabled={busy} value={form.category_id} onChange={(e) => setForm((s) => ({ ...s, category_id: e.target.value }))}><option value="">Semua kategori</option>{options.categories.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></div>
      <div><label className="label" htmlFor={prefix + 'weight'}>Bobot *</label><input id={prefix + 'weight'} className="input" type="number" min={0.01} max={100} step={0.01} required disabled={busy} value={form.weight} onChange={(e) => setForm((s) => ({ ...s, weight: e.target.value }))} /></div>
      <div><label className="label" htmlFor={prefix + 'order'}>Urutan tampilan</label><input id={prefix + 'order'} className="input" type="number" step={1} disabled={busy} value={form.display_order} onChange={(e) => setForm((s) => ({ ...s, display_order: e.target.value }))} /></div>
    </div><label className="text-sm flex gap-2"><input type="checkbox" checked={form.is_active} disabled={busy} onChange={(e) => setForm((s) => ({ ...s, is_active: e.target.checked }))} />Parameter aktif</label>{error && <p role="alert" className="text-sm text-danger-400">{error}</p>}<div className="flex flex-wrap justify-end gap-2"><button type="button" className="btn-secondary" disabled={busy} onClick={() => { setEditing(null); setForm(empty); }}>Parameter baru</button><button className="btn-primary" disabled={busy}>Simpan Rubrik</button></div></form>
  </dialog>;
}
